import{_ as o,o as r,c as d,ag as n}from"./chunks/framework.KxDd3USm.js";const l=JSON.parse('{"title":"04.2 面向对象分析与设计过程 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"04-面向对象与设计模式/02-分析与设计过程.md","filePath":"04-面向对象与设计模式/02-分析与设计过程.md"}'),s={name:"04-面向对象与设计模式/02-分析与设计过程.md"};function g(a,t,e,u,q,h){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="_04-2-面向对象分析与设计过程-★★" tabindex="-1">04.2 面向对象分析与设计过程 ★★ <a class="header-anchor" href="#_04-2-面向对象分析与设计过程-★★" aria-label="Permalink to &quot;04.2 面向对象分析与设计过程 ★★&quot;">​</a></h1><h3 id="_2-1-为什么先要有-过程" tabindex="-1">2.1 为什么先要有&quot;过程&quot; <a class="header-anchor" href="#_2-1-为什么先要有-过程" aria-label="Permalink to &quot;2.1 为什么先要有&quot;过程&quot;&quot;">​</a></h3><p>很多人以为&quot;面向对象&quot;就是&quot;写类&quot;。但类从哪来？属性怎么定？关系怎么画？——<strong>不解决这些问题，画出来的类图就是凭感觉摆的</strong>。OOA（面向对象分析）解决&quot;<strong>要什么</strong>&quot;，OOD（面向对象设计）解决&quot;<strong>怎么搭</strong>&quot;，两步各有一套固定动作。考试既考选择题（问&quot;下面哪一步属于 OOA&quot;），更是 UML 案例题的<strong>解题骨架</strong>——案例题让你补类名、补方法名，靠的就是 OOD 的&quot;定义属性/定义服务&quot;这两步。</p><h3 id="_2-2-ooa-四步-背顺序-选择题按顺序出干扰项-★★" tabindex="-1">2.2 OOA 四步（背顺序，选择题按顺序出干扰项）★★ <a class="header-anchor" href="#_2-2-ooa-四步-背顺序-选择题按顺序出干扰项-★★" aria-label="Permalink to &quot;2.2 OOA 四步（背顺序，选择题按顺序出干扰项）★★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th><th>落在案例题里的动作</th></tr></thead><tbody><tr><td>① <strong>认定对象</strong></td><td>从需求描述里挑出<strong>名词</strong>候选</td><td>说明文字里的名词就是类名候选（读者、图书、借阅记录）</td></tr><tr><td>② <strong>组织对象</strong></td><td>把同类对象<strong>抽象成类</strong>，抽出公共属性</td><td>学生读者/教师读者 → 抽父类&quot;读者&quot;</td></tr><tr><td>③ <strong>描述对象间的相互作用</strong></td><td>谁和谁有往来、什么关系、多重性</td><td>读者 1 — 1..* 借阅记录</td></tr><tr><td>④ <strong>基于对象的操作</strong></td><td>每个对象要提供哪些操作（服务）</td><td>补<strong>方法名</strong>（checkOut、getForCheckOut）</td></tr></tbody></table><p><strong>记忆口诀</strong>：<strong>认对象 → 组类 → 拉关系 → 定操作</strong>（&quot;认组拉定&quot;）。</p><h3 id="_2-3-ood-五步-★★" tabindex="-1">2.3 OOD 五步 ★★ <a class="header-anchor" href="#_2-3-ood-五步-★★" aria-label="Permalink to &quot;2.3 OOD 五步 ★★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>做什么</th></tr></thead><tbody><tr><td>① <strong>识别类及对象</strong></td><td>在分析结果上补足实现层面的类（控制类、边界类、工具类）</td></tr><tr><td>② <strong>定义属性</strong></td><td>每个类需要存哪些数据（书号、书名、定价）</td></tr><tr><td>③ <strong>定义服务</strong></td><td>每个类要对外提供什么方法（借出、归还、计算应还日期）</td></tr><tr><td>④ <strong>识别关系</strong></td><td>泛化/关联/聚合/组合/依赖，以及多重性</td></tr><tr><td>⑤ <strong>识别包</strong></td><td>把类按职责分组打包，定义包间依赖</td></tr></tbody></table><p><strong>反例演示（易错）</strong>：考题问&quot;下列哪一项属于<strong>面向对象设计</strong>而非分析&quot;——判别标准是&quot;<strong>有没有落到实现细节</strong>&quot;。<strong>&quot;认定对象&quot;是分析</strong>（还在业务层挑名词），<strong>&quot;定义属性/服务&quot;是设计</strong>（已经在写类的成员了）。别把&quot;识别类及对象&quot;错认成分析的&quot;认定对象&quot;：前者是实现视角的补全，后者是需求视角的提取。</p><h3 id="_2-4-ood-七大原则-送分题-也决定-为什么这么设计-★★" tabindex="-1">2.4 OOD 七大原则（送分题，也决定&quot;为什么这么设计&quot;）★★ <a class="header-anchor" href="#_2-4-ood-七大原则-送分题-也决定-为什么这么设计-★★" aria-label="Permalink to &quot;2.4 OOD 七大原则（送分题，也决定&quot;为什么这么设计&quot;）★★&quot;">​</a></h3><p>这七条是判断题与案例题&quot;为什么要用设计模式&quot;的<strong>答题依据</strong>——注意它们的共同指向：<strong>都反对&quot;改一处牵动全身&quot;的紧耦合写法</strong>。</p><table tabindex="0"><thead><tr><th>原则</th><th>一句话</th><th>反对什么写法（反例）</th></tr></thead><tbody><tr><td><strong>单一职责</strong>（SRP）</td><td>一个类只负责一件事</td><td>一个 <code>BookManager</code> 既管借还、又管打印报表、又管发短信</td></tr><tr><td><strong>开放-封闭</strong>（OCP）</td><td><strong>对扩展开放、对修改封闭</strong></td><td>每加一种支付方式就去改 <code>PaymentService</code> 里的 <code>switch</code></td></tr><tr><td><strong>里氏替换</strong>（LSP）</td><td>子类<strong>可以替换</strong>父类（不破坏父类的约定）</td><td>子类重写后抛异常/收紧前置条件，父类能用的地方用不了</td></tr><tr><td><strong>依赖倒置</strong>（DIP）</td><td>依赖<strong>抽象</strong>，不依赖具体实现；<strong>针对接口编程</strong></td><td>高层业务类里直接 <code>new MySQLDao()</code></td></tr><tr><td><strong>接口隔离</strong>（ISP）</td><td>多个专门接口优于一个总接口</td><td>一个 20 个方法的 <code>IAllService</code>，实现类被迫空实现一堆方法</td></tr><tr><td><strong>组合重用</strong>（CRP）</td><td>尽量用<strong>组合</strong>而不是继承来重用</td><td>为了复用几个方法就继承一个不相干的类（继承层级爆炸）</td></tr><tr><td><strong>迪米特</strong>（LoD，最少知识）</td><td>一个对象对别的对象<strong>知道得越少越好</strong></td><td><code>a.getB().getC().getD().doX()</code> 层层穿透调用</td></tr></tbody></table><p><strong>依赖倒置的经典原话</strong>（真题原句）：&quot;<strong>抽象不应该依赖于细节，细节应该依赖于抽象</strong>；高层模块不应该依赖低层模块，两者都应该依赖于抽象。&quot;——这句话只要出现，答案就是<strong>依赖倒置原则</strong>。</p><p><strong>里氏替换与多态的关系</strong>：多态能成立，前提正是里氏替换——&quot;父类的地方放子类不出错&quot;。所以 LSP 是<strong>多态的原则性表述</strong>。</p><h3 id="_2-5-包设计原则-低频-认识就够" tabindex="-1">2.5 包设计原则（低频，认识就够） <a class="header-anchor" href="#_2-5-包设计原则-低频-认识就够" aria-label="Permalink to &quot;2.5 包设计原则（低频，认识就够）&quot;">​</a></h3><p>另有六条更细的包（package）级原则，考试偶见，<strong>不要与七大原则混记</strong>：</p><table tabindex="0"><thead><tr><th>原则</th><th>一句话</th></tr></thead><tbody><tr><td>重用发布等价</td><td>重用的粒度就是发布的粒度</td></tr><tr><td>共同封闭</td><td>一个变化应只影响一个包内的类，不波及其他包</td></tr><tr><td>共同重用</td><td>重用了包中一个类，就得重用包中所有类</td></tr><tr><td>无环依赖</td><td>包的依赖图中<strong>不允许有环</strong></td></tr><tr><td>稳定依赖</td><td>朝着<strong>稳定</strong>的方向依赖（不稳定的包依赖稳定的包）</td></tr><tr><td>稳定抽象</td><td>包的<strong>抽象程度应与其稳定程度一致</strong>（越稳定越抽象）</td></tr></tbody></table><p><strong>真题原题形式</strong>：&quot;若重用了一个包中的某个类，就要重用该包中的所有类，这属于（ ）原则&quot; → <strong>共同重用原则</strong>。这句题干里的&quot;某个 → 所有&quot;就是它的唯一识别特征。</p><p><strong>应试动作</strong>：七大原则<strong>必须背名字 + 一句话</strong>（选择题直接考原话）；包原则只背&quot;共同重用&quot;&quot;共同封闭&quot;两条题眼，其余见过即可。案例题里问&quot;采用什么设计模式更好、为什么&quot;，答题时<strong>顺手引用原则名</strong>（如&quot;符合开放-封闭原则，新增算法无需修改原有代码&quot;）能显著提分。</p>',19)])])}const i=o(s,[["render",g]]);export{l as __pageData,i as default};
